cd /workspace && python3 << 'EOF'
import json,re
def norm(s):
    m=re.search(r'user\n(.*?)\nassistant', s, re.S)
    q=m.group(1) if m else s
    return re.sub(r'\s+',' ',q).strip()
val={norm(json.loads(l)['input']) for l in open('results/run100/val_generations/0.jsonl')}
print('distinct val prompts:',len(val))
for step in [1,50,100]:
    tr={norm(json.loads(l)['input']) for l in open(f'results/run100/rollouts/{step}.jsonl')}
    ov=val & tr
    print(f'rollout {step:3d}: distinct train prompts={len(tr)}  overlap with val={len(ov)}')
EOF
